import { ref, computed, watch, type ComputedRef, type Ref } from 'vue';
import { slugify } from './rule-builder-model';

// Shared behaviour for the "Rule key" machine-key field, used by both the
// custom-validation rule builder and the form-builder selection-rule drawer:
//
//   - For a NEW rule the key is auto-derived from the display name via slugify
//     (which mirrors the backend slug) and shown read-only behind a pencil.
//   - Clicking the pencil (unlockRuleKey) lets the user set the key by hand;
//     from then on the name no longer regenerates it.
//   - In edit mode (or for otherwise read-only rules) the key is immutable.
export interface UseRuleKeyOptions {
  // Reactive getter for the display name that seeds the key.
  getName: () => string;
  // Setter for the bound rule key.
  setKey: (value: string) => void;
  // Edit mode → the key is immutable and always read-only.
  isEdit: () => boolean;
  // Extra read-only source (e.g. system-default rules); optional.
  isReadOnly?: () => boolean;
}

export interface UseRuleKey {
  ruleKeyEditable: Ref<boolean>;
  ruleKeyReadonly: ComputedRef<boolean>;
  unlockRuleKey: () => void;
  onRuleKeyInput: (value: string | number | null) => void;
  resetRuleKey: () => void;
}

export function useRuleKey(options: UseRuleKeyOptions): UseRuleKey {
  const ruleKeyEditable = ref(false);
  // Latches once the user takes over so the name no longer regenerates the key.
  const manual = ref(false);

  const ruleKeyReadonly = computed(
    () => (options.isReadOnly?.() ?? false) || options.isEdit() || !ruleKeyEditable.value,
  );

  // Auto-derive the machine key from the display name for NEW rules, until the
  // user takes manual control. Never touch it in edit mode.
  watch(
    () => options.getName(),
    (name) => {
      if (options.isEdit() || manual.value) return;
      options.setKey(slugify(name || ''));
    },
  );

  // Pencil click: unlock the auto-derived key so the user can set it by hand.
  function unlockRuleKey() {
    ruleKeyEditable.value = true;
    manual.value = true;
  }

  // Normalize typed input toward the machine-key shape — same charset and
  // 100-char cap as slugify. A trailing separator is kept while typing so the
  // user can enter multi-word keys; leading separators are dropped.
  function onRuleKeyInput(value: string | number | null) {
    options.setKey(
      String(value ?? '')
        .toLowerCase()
        .replace(/[^a-z0-9]+/g, '_')
        .replace(/^_+/, '')
        .slice(0, 100),
    );
  }

  // Return to the locked / auto-derive state — used when a reused component
  // (e.g. the drawer) starts editing a different rule.
  function resetRuleKey() {
    ruleKeyEditable.value = false;
    manual.value = false;
  }

  return { ruleKeyEditable, ruleKeyReadonly, unlockRuleKey, onRuleKeyInput, resetRuleKey };
}
